import{_ as t,c as e,o as s,a6 as a}from"./chunks/framework.DQNfPlXe.js";const _=JSON.parse('{"title":"Nest.js","description":"","frontmatter":{"date":"2025-08-27T00:00:00.000Z","title":"Nest.js"},"headers":[],"relativePath":"work/Nest/Nestjs.md","filePath":"work/Nest/Nestjs.md","lastUpdated":1756284786000}'),r={name:"work/Nest/Nestjs.md"},l=a('<h1 id="nest-js" tabindex="-1">Nest.js <a class="header-anchor" href="#nest-js" aria-label="Permalink to &quot;Nest.js&quot;">​</a></h1><img width="200" src="https://docs.nestjs.com/assets/logo-small-gradient.svg"><h2 id="官网" tabindex="-1">官网 <a class="header-anchor" href="#官网" aria-label="Permalink to &quot;官网&quot;">​</a></h2><ul><li><a href="https://docs.nestjs.com/" target="_blank" rel="noreferrer">官网</a></li><li><a href="https://nestjs.inode.club/" target="_blank" rel="noreferrer">中文文档网站</a></li></ul><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>Nest.js 是一个用于构建高效、可扩展的 Node.js 服务器端应用程序的框架。它使用 TypeScript 构建，结合了面向对象编程、函数式编程和函数响应式编程的元素。</p><h3 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h3><ul><li><strong>TypeScript 优先</strong>: 完全使用 TypeScript 编写，提供优秀的类型安全性和开发体验</li><li><strong>依赖注入</strong>: 内置强大的依赖注入容器，便于管理应用程序组件</li><li><strong>模块化架构</strong>: 基于模块的设计，使应用程序结构清晰、易于维护</li><li><strong>装饰器模式</strong>: 大量使用装饰器，简化代码并提高可读性</li><li><strong>开箱即用</strong>: 内置支持 Express 和 Fastify，无需额外配置</li><li><strong>微服务支持</strong>: 原生支持微服务架构，包括 gRPC、MQTT、Redis 等</li><li><strong>WebSocket 支持</strong>: 内置 WebSocket 网关，便于实时通信</li><li><strong>GraphQL 支持</strong>: 原生支持 GraphQL，包括代码优先和模式优先方法</li><li><strong>测试友好</strong>: 提供完整的测试工具和实用程序</li></ul><h3 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h3><p>Nest.js 借鉴了 Angular 的设计理念，提供了一个结构化的方式来构建 Node.js 应用程序。它强调：</p><ul><li><strong>可扩展性</strong>: 通过模块化设计支持大型应用程序</li><li><strong>可维护性</strong>: 清晰的架构和依赖注入使代码易于理解和维护</li><li><strong>可测试性</strong>: 内置的测试支持使单元测试和集成测试变得简单</li><li><strong>可重用性</strong>: 组件可以在不同的模块和应用程序中重用</li></ul><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ul><li>企业级 Node.js 应用程序</li><li>微服务架构</li><li>RESTful API 开发</li><li>GraphQL API 开发</li><li>实时应用程序（WebSocket）</li><li>全栈 TypeScript 项目</li></ul><h2 id="相关笔记" tabindex="-1">相关笔记 <a class="header-anchor" href="#相关笔记" aria-label="Permalink to &quot;相关笔记&quot;">​</a></h2><ul><li><a href="/work/Nest/创建Nest项目.html">创建Nest项目</a></li></ul>',15),i=[l];function o(n,h,c,d,g,u){return s(),e("div",null,i)}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
